    "keyNotes": "• Greek Classical Drama:\n  - Originated in ancient Athens during festivals honoring Dionysus, god of wine and fertility.\n  - Aristotle's Poetics: Defined tragedy as the imitation of an action that is serious, complete, and of significant magnitude, producing catharsis (purgation of pity and fear).\n• The Tragic Dilemma:\n  - Hubris (arrogant pride): Tragic hero defies gods or moral warnings, triggering Nemesis (retribution).\n  - Fate vs. Free Will: Protagonists struggle against inescapable divine prophecies (e.g. Oedipus Rex by Sophocles).\n  - Dramatic Irony: The audience knows Oedipus is cursing himself long before he discovers his own true identity.\n  - Anagnorisis (Moment of critical discovery or self-realization) and Peripeteia (Sudden reversal of fortune).",
