    "keyNotes": "• Feminist Criticism in African Literature:\n  - Challenges traditional patriarchal stereotyping of African women as passive, submissive chattels, silent childbearers, or sacrificial victims.\n  - Celebrates female resilience, economic independence, intellectual agency, and sisterhood.\n• Key Themes in African Feminist Texts:\n  - The Burden of Motherhood & Barrenness: Traditional society often judges a woman's entire human worth by her fertility and ability to bear male heirs (e.g. Buchi Emecheta's *The Joys of Motherhood*).\n  - Polygyny & Co-Wife Rivalry: The emotional tensions, domestic politics, and economic insecurities embedded in polygamous family structures.\n  - Cultural Traditions vs. Modern Autonomy: Child marriage, female circumcision, widowhood rites, and dowry inflation contrasted with modern legal rights and tertiary education.\n• Celebrated African Female Writers:\n  - Ama Ata Aidoo (*Anowa*, *Changes: A Love Story*): Explores Ghanaian women balancing modern careers with traditional marriage expectations.\n  - Flora Nwapa (*Efuru*): The pioneer of African women's literature, highlighting women's commercial autonomy and financial independence.",
