    "keyNotes": "• Major Ethno-Linguistic Classifications in Ghana:\n  - Kwa Linguistic Sub-Group:\n    * The Akan: Largest ethnic group; traditions indicate origins from the ancient Ghana Empire or dispersal from the Bono Manso / Pra-Offin basin. Divided into Fante, Asante, Akuapem, Akyem, Bono, etc.\n    * The Ga-Adangbe: Migrated from the east (around modern Benin/Nigeria) and settled along the coastal plains of the Greater Accra and Eastern regions.\n    * The Ewe: Traced migrations from Ketu (Benin) through Notsie in modern Togo under King Agokoli before settling in the Volta Basin.\n  - Gur Linguistic Sub-Group:\n    * The Mole-Dagbon: Comprising Dagomba, Mamprusi, Mossi, and Nanumba; founded by Tohazie (the Red Hunter) and Naa Gbewaa with headquarters at Pusiga.\n    * The Grusi and Gurma peoples of the Upper East and Upper West regions.\n  - The Guan: Oldest documented surviving settlers scattered across modern Ghana (Gonja, Efutu, Anum, Larteh).",
