    "keyNotes": "• Political Systems:\n  - Centralized States: Had a single recognized supreme ruler (King/Paramount Chief), hierarchical administration, and standing armies (e.g. Asante Kingdom, Dagbon, Gonja).\n  - Segmentary / Acephalous Societies: Lacked centralized kingship; governance was decentralized, based on lineage heads, clan elders, and earth priests (Tindana) (e.g. Talensi, Konkomba, early Guan).\n• The Akan Chieftaincy Institution:\n  - The Omanhene (Paramount Chief): Political and military head; sacred custodian of the ancestral Golden/Black Stools. Bound by oath to rule according to custom.\n  - The Ohemmaa (Queen Mother): Co-ruler; kingmaker who has the sole customary prerogative of nominating the new chief after consulting clan elders; moral advisor.\n  - Council of Elders: Heads of royal lineages who check royal absolutism.\n  - The Asafo Companies: Military and civic youth organizations responsible for defense, communal labor, and voicing public grievances.",
