    "keyNotes": "• Nature & Organization: Ancient trade linking North Africa (Berbers, Arabs) and West Africa across the Sahara Desert. Camels ('ships of the desert') enabled traversing arid wastes in large caravans.\n• Primary Trade Commodities:\n  - From West Africa: Gold (from Akan and Bambuk goldfields), kola nuts (forest zones), ivory, and slaves.\n  - From North Africa & Mediterranean: Rock salt (from Taghaza), cowrie shells, textiles, swords, glass beads, and dried dates.\n• Method of Exchange: Silent barter (dumb barter) in early phases, later using cowries and gold dust as currency.\n• Historical Consequences:\n  - Rise of Sudanic Empires: Ghana, Mali, and Songhai grew wealthy by levying taxes on trade goods.\n  - Introduction of Islam: Muslim traders and scholars brought Arabic literacy, architectural styles, administrative book-keeping, and the Sharia legal code.\n  - Urbanization: Growth of great commercial terminals like Timbuktu, Gao, Jenne, and Begho.",
