    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• The Triangular Trade Network:\n  - Outward Passage: European manufactured goods (firearms, gunpowder, textiles, alcoholic spirits) shipped to the West African coast.\n  - Middle Passage: Enslaved Africans transported across the Atlantic Ocean under horrific, inhuman conditions to work on sugar, cotton, and tobacco plantations in the Americas.\n  - Homeward Passage: Raw plantation produce (sugar, tobacco, rum, cotton) transported back to industrializing Europe.\n• Capture & Internment:\n  - Enslaved persons obtained through warfare, raids, judicial corruption, and kidnapping. Kept in suffocating castle dungeons before embarkation through the 'Door of No Return'.\n• Catastrophic Effects on the Gold Coast:\n  - Massive demographic loss of millions of young, productive individuals.\n  - Chronic insecurity, tribal warfare, destruction of indigenous crafts and agricultural systems.\n• Abolition (1807): Championed by humanitarians (William Wilberforce, Olaudah Equiano), economic shifts toward industrial machinery, and slave rebellions in Haiti.",
