    "keyNotes": "• Steps to British Colonization:\n  - The Bond of 1844: Signed on March 6, 1844, between British Lieutenant-Governor Commander H.W. Hill and coastal Fante chiefs. Primarily an agreement for judicial cooperation; Britain later distorted it into a sovereign treaty.\n  - The Poll Tax Ordinance (1852): British attempt to levy direct taxes (1 shilling per head); failed due to massive coastal boycott and non-representation.\n  - The Sagrenti War (1874): British expedition under Sir Garnet Wolseley invaded Kumasi, looted royal regalia, burned Kumasi, and formally declared the coastal zone the Gold Coast Colony.\n• Anti-Colonial Resistance:\n  - The Yaa Asantewaa War (1900): British Governor Sir Frederick Hodgson demanded to sit on the Golden Stool (sika dwa kofi). Queen Mother Nana Yaa Asantewaa of Ejisu led the Asante army in an epic siege of the British fort in Kumasi to defend the spiritual soul of the Asante nation.\n  - Resistance of the Aborigines Rights Protection Society (ARPS) in 1897 against the Lands Bill.",
