    "title": "The Rise of Nationalist Movements & Political Parties",
    "description": "Early nationalist protests, the 1948 Accra Riots, the Watson Commission, formation of the UGCC (1947) and CPP (1949), and 'Self-Government Now'.",
    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Evolution of Nationalism:\n  - Phase 1: Elite-led constitutional protests (NCBWA, ARPS) demanding legislative representation and civil service openings.\n  - Phase 2: Mass-based radical nationalism triggered by post-WWII socio-economic crises (ex-servicemen unemployment, high cost of living, Association of West African Merchants cartel).\n• The 1948 Crossroads:\n  - February 28, 1948 Crossroads Shooting: British Police Superintendent Imray shot unarmed ex-servicemen (Sergeant Adjetey, Corporal Attipoe, Private Odartey Lamptey) marching to Osu Castle.\n  - Spontaneous 1948 Accra Riots and looting of European stores. British colonial government arrested the 'Big Six' (J.B. Danquah, Kwame Nkrumah, William Ofori-Atta, Akufo-Addo, Ako Adjei, Obetsebi-Lamptey).\n• The Watson Commission & the Coussey Committee: Recommended full self-government for the Gold Coast.\n• The Breakaway: In June 1949, Kwame Nkrumah broke from the conservative UGCC to form the Convention People's Party (CPP) with the slogan 'Self-Government NOW'.",
