    "keyNotes": "• Indirect Rule Defined: A British colonial administrative system whereby the colonized people were governed through their own traditional chiefs and customary political institutions under the supervision of British District Commissioners.\n• Underlying Rationale (Lord Frederick Lugard):\n  - Acute shortage of British administrative personnel.\n  - Lack of financial revenue to fund direct colonial bureaucracy.\n  - Language and cultural barriers; avoiding native uprisings by preserving familiar chieftaincy structures.\n• Operational Machinery:\n  - Native Authorities: Chiefs recognized by colonial warrant to maintain peace, recruit labor, and collect direct taxes.\n  - Native Courts: Chiefs arbitrated local civil and customary disputes under colonial oversight.\n  - Native Treasuries: Collected market tolls, poll taxes, and court fines.\n• Conflict & Criticism:\n  - Traditional chiefs became accountable to British Governor rather than their own subjects, leading to frequent destoolments.\n  - Deliberate alienation of the Western-educated elite (lawyers, doctors, journalists) who were excluded from political power.",
