    "keyNotes": "• The Cocoa Revolution:\n  - In 1879, Tetteh Quarshie, an indigenous blacksmith, returned from Fernando Po (Equatorial Guinea) with Amelonado cocoa pods and established an experimental farm at Mampong-Akwapim.\n  - Rapidly adopted by peasant farmers using traditional matrilineal and patrilineal land tenure (abusa and abunu systems).\n  - By 1911, the Gold Coast surpassed all world nations to become the largest global producer and exporter of cocoa.\n• Extractive Minerals & Railways:\n  - Gold mining transformed from indigenous panning into capital-intensive European shaft mining in Obuasi (Ashanti Goldfields Corporation, 1897), Tarkwa, and Prestea.\n  - Colonial Railway Network: Western Line (Sekondi to Tarkwa and Kumasi, 1903) built specifically to evacuate gold and timber; Eastern Line (Accra to Kumasi, 1923) built for cocoa.\n• Structural Weakness: Created an extractive, raw-material export economy dangerously dependent on cocoa and vulnerable to volatile world commodity price shocks.",
