    "title": "The Great Medieval Empires of West Africa: Ghana, Mali & Songhai",
    "description": "State formation in the Western Sudan, gold-salt trade, Mansa Musa's pilgrimage, Timbuktu as a center of scholarship, Sunni Ali, and the fall of Songhai.",
    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Ancient Ghana Empire (Wagadu, c. 300–1240 AD):\n  - Capital: Kumbi Saleh. Ruled by Soninke monarchs titled the \"Ghana\" (War Chief) and \"Kaya Maghan\" (King of Gold).\n  - Economic Power: Controlled the trans-Saharan gold-salt trade between the Bambuk goldfields and North African salt deposits at Taghaza.\n  - Decline: Raids by the Almoravid Berber invaders in the 11th century, ecological drought, and tributary rebellions.\n• Mali Empire (c. 1230–1600 AD):\n  - Founder: Sundiata Keita (The Lion King), who defeated King Sumanguru Kante of Sosso at the epic Battle of Kirina (1235 AD) and established the Kouroukan Fouga (constitutional charter).\n  - Mansa Kankan Musa (1312–1337): Led the historic 1324 pilgrimage (Hajj) to Mecca accompanied by 60,000 men and tons of pure gold; spent so lavishly in Cairo that he caused local gold inflation for over a decade.\n  - Architecture & Scholarship: Commissioned architect Abu Ishaq al-Sahili to build the Great Djinguereber Mosque and Sankore University in Timbuktu.\n• Songhai Empire (c. 1464–1591 AD):\n  - Capital: Gao.\n  - Sunni Ali Ber (1464–1492): Military conqueror who built a professional cavalry and naval fleet along the Niger River.\n  - Askia Muhammad Toure (Askia the Great, 1493–1528): Promoted Islamic law, standardized weights and measures, and expanded schools of theology and astronomy in Timbuktu.\n  - Collapse: Defeated at the Battle of Tondibi (1591) by Moroccan invaders armed with early gunpowder firearms (arquebuses).",
