    "keyNotes": "• Weathering Defined: The in-situ (on-site) disintegration and decomposition of rocks by physical, chemical, and biological agents without transportation.\n• Weathering Processes:\n  - Physical / Mechanical: Disintegration into smaller fragments without chemical alteration. Mechanisms: Exfoliation (onion-skin peeling due to rapid diurnal temperature changes in northern Ghana), frost wedging, block disintegration.\n  - Chemical: Rock decay involving chemical reaction. Mechanisms: Carbonation (acid rain dissolving limestone), Oxidation (iron minerals rusting and crumbling), Hydration, Hydrolysis. Prevalent in humid southern Ghana.\n  - Biological: Fracturing by plant roots, burrowing earthworms, rodents, and human quarrying.\n• Mass Wasting: Downslope movement of weathered rock debris under the direct force of gravity.\n  - Slow movements: Soil creep (bent tree trunks, tilted fence posts).\n  - Rapid movements: Landslides, rockfalls, mudflows (common along the Aburi-Accra escarpment during torrential rainy seasons).",
