    "keyNotes": "• Major Vegetation Belts of Ghana & West Africa:\n  - Mangrove Swamps: Dense, tangle-rooted saline trees found along coastal lagoons and river estuaries.\n  - Tropical Rainforest (Evergreen & Deciduous): Dense multi-layered canopy (emergent, canopy, understory), buttress roots, lianas, epiphytes, high species diversity (Obeche, Mahogany, Odum).\n  - Savanna Woodlands (Guinea & Sudan Savanna): Tall grasses, scattered fire-resistant drought-tolerant deciduous trees (Baobab, Shea butter, Acacia, Dawadawa). Trees have thick bark and waxy leaves.\n  - Coastal Savanna: Short grasses and scrubland occurring along the southeastern coastal strip of Ghana due to low rainfall.\n• Soils & Degradation:\n  - Laterite (Oxisols): Heavily leached reddish-brown tropical soils rich in iron and aluminum oxides, prone to hardening when exposed.\n  - Deforestation & Desertification: Driven by illegal mining (galamsey), timber felling, slash-and-burn farming, and bushfires.",
