    "keyNotes": "• Transport Modes in Ghana:\n  - Road Transport: Handles over 95% of domestic freight and passenger movement. High flexibility, door-to-door delivery, but plagued by road accidents, poor feeder roads, and vehicular congestion.\n  - Maritime Transport: Deep-sea ports at Tema and Takoradi handle foreign import/export traffic.\n  - Railway: Historic colonial lines (Western, Eastern, Central lines) connected mining and cocoa centers to the ports; currently undergoing modernization.\n  - Air Transport: Kotoka International Airport (Accra) and regional airports (Kumasi, Tamale, Sunyani, Wa).\n• Regional Integration:\n  - ECOWAS (formed in Lagos, 1975): Promotes free movement of goods, capital, and persons without visas.\n  - AfCFTA (Secretariat headquartered in Accra, Ghana): Aims to create a single continental market of 1.3 billion consumers.\n  - Obstacles to Trade: Multiplicity of currencies, non-tariff barriers, customs checkpoints extortion, language divide (Anglophone vs. Francophone), and poor cross-border transport infrastructure.",
