    "isFreeTrial": true,
    "isVip": false,
    "keyNotes": "• The Three Fundamental Questions:\n  1. What to produce? (Which commodities and in what quantities?)\n  2. How to produce? (What combination of resources and technology: labor-intensive vs. capital-intensive?)\n  3. For whom to produce? (How will the national output be distributed among households?)\n• Comparison of Economic Systems:\n  - Traditional Economy: Production guided by customs, rituals, and heredity; subsistence farming and barter trade dominate.\n  - Free Market / Capitalist Economy: Private ownership of productive resources; allocation dictated entirely by the price mechanism (invisible hand); driven by profit motive and consumer sovereignty.\n  - Command / Socialist Economy: State owns all means of production; central planning committee determines prices, quotas, and resource allocation.\n  - Mixed Economy: Combines private enterprise with government intervention. Private sector produces for profit; public sector regulates, provides public goods, and protects the vulnerable (e.g. Ghana).",
