    "keyNotes": "• Factors of Production & Factor Rewards:\n  - Land (Reward: Rent), Labor (Reward: Wages/Salaries), Capital (Reward: Interest), Entrepreneurship (Reward: Profit).\n• Time Horizons:\n  - Short Run: Period in which at least one factor of production is fixed (usually capital/land), while others are variable (labor).\n  - Long Run: Time frame sufficiently long that all factors of production become variable.\n• The Law of Diminishing Marginal Returns:\n  - States that as successive units of a variable factor (labor) are added to fixed factors (land), a point will eventually be reached where the addition to total output (Marginal Product) begins to decline.\n• Cost Concepts:\n  - Fixed Cost (FC): Costs that do not vary with output level (e.g. factory rent, machinery depreciation).\n  - Variable Cost (VC): Costs that change directly with output (e.g. raw materials, electricity, casual labor).\n  - Total Cost (TC) = FC + VC.\n  - Marginal Cost (MC): The additional cost incurred from producing one extra unit of output (Change in TC / Change in Q).",
