    "keyNotes": "• Public Finance & Government Revenue:\n  - Primary revenue source is Taxation (Direct taxes: personal income tax, corporate tax; Indirect taxes: VAT, customs duties, excise duties).\n  - Canons of Taxation (Adam Smith): Equity, Certainty, Convenience, Economy.\n• Fiscal Policy:\n  - Use of government revenue (taxation) and expenditure to influence aggregate demand and macroeconomic stability.\n  - Budget Deficit (Expenditure > Revenue) vs. Budget Surplus.\n• International Trade:\n  - Basis of Trade: Principle of Comparative Advantage (David Ricardo)—a country should specialize in producing goods where it has the lowest opportunity cost.\n• Balance of Payments (BOP):\n  - A systematic accounting record of all economic transactions between residents of a country and the rest of the world over one year.\n  - Current Account (visible trade: goods, invisible trade: services, income) and Capital/Financial Account.\n  - BOP Deficit: When total external payments exceed total foreign receipts. Remedied by currency depreciation, import substitution, and export diversification.",
