    "keyNotes": "• Population Theories:\n  - Malthusian Theory (Thomas Malthus, 1798): Population grows at a geometric progression (1, 2, 4, 8, 16...), while food production grows at an arithmetic progression (1, 2, 3, 4, 5...). Without preventative checks (moral restraint, delayed marriage), positive checks (famine, disease, war) will bring population down to subsistence levels.\n  - Demographic Transition Theory: Three stages of demographic evolution:\n    1. High stationary stage: High birth rate and high death rate (primitive agrarian society).\n    2. Early expanding stage: High birth rate and rapidly falling death rate due to modern medicine, causing population explosion (e.g. developing West Africa).\n    3. Low stationary stage: Low birth rate and low death rate (industrialized nations).\n• Age Structure & Dependency Burden:\n  - Ghana has a broad-based, youthful population pyramid (> 40% under 15 years), resulting in a high age dependency ratio: (Dependents [0-14 + 65+]) / (Working Population [15-64]) * 100.\n  - Puts extreme pressure on state education, health budgets, and capital formation.",
