    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• The Demand for Labor:\n  - Derived Demand: Labor is not demanded for its own sake, but for the goods and services it helps produce.\n  - Marginal Revenue Productivity (MRP) Theory: A profit-maximizing employer will hire workers up to the point where the Marginal Revenue Product of Labor (MRPL) equals the Marginal Wage Cost (W = MRPL).\n• Supply of Labor:\n  - Influenced by population size, working age limits, wage rates, working conditions, and education requirements.\n  - Backward-Bending Supply Curve of Labor: At very high wages, the income effect outweighs the substitution effect, and workers prefer leisure over extra hours.\n• Wage Differentials in Ghana:\n  - Reasons wages differ: Differences in natural abilities, length and cost of training, risk and danger (e.g. underground mining), non-monetary fringe benefits, and trade union bargaining strength.\n• Minimum Wage Legislation:\n  - National Tripartite Committee in Ghana (Government, Employers, TUC) fixes the daily minimum wage to protect vulnerable workers from exploitation.",
