    "keyNotes": "• Growth vs. Development:\n  - Economic Growth: A quantitative, sustained increase in a country's real Gross Domestic Product (GDP) or national output over time. Measured by annual percentage increase in real GDP.\n  - Economic Development: A broader qualitative and structural transformation involving economic growth plus significant improvements in living standards, literacy, health, income distribution, and institutional reforms.\n• Measurement Indicators:\n  - GDP per Capita = (Total Real GDP) / (Total Population).\n  - Human Development Index (HDI): Composite metric created by UNDP combining:\n    1. Life expectancy at birth (health).\n    2. Expected and mean years of schooling (education).\n    3. Gross National Income (GNI) per capita (standard of living).\n• The Vicious Circle of Poverty (Ragnar Nurkse):\n  - Low income -> Low savings -> Low investment -> Low capital accumulation -> Low productivity -> Low income.\n• Sustainable Development: Meeting present needs without compromising the ability of future generations to meet their own needs.",
