    "keyNotes": "• Biblical Accounts of Creation:\n  - Genesis 1:1–2:4a (First Account / Priestly tradition): God creates the universe out of void and darkness through divine spoken word (\"Let there be...\"). Systematic 6-day progression culminating in the creation of humankind (male and female in the image of God) and resting on the 7th day (Sabbath).\n  - Genesis 2:4b–25 (Second Account / Yahwist tradition): More intimate, anthropomorphic. Man is formed from the dust of the ground, and God breathes the breath of life into his nostrils. Woman is fashioned from man's rib.\n• Attributes of God:\n  - Omnipotence: All-powerful; creates ex-nihilo (out of nothing).\n  - Omniscience: All-knowing.\n  - Omnipresence: Present everywhere throughout creation.\n  - Sovereign Sustainer: Actively upholds the cosmos, controls climate and seasons, and directs the moral destiny of nations.\n• Human Responsibility: Humans are appointed as divine stewards/caretakers over God's earth, mandating environmental conservation.",
