    "keyNotes": "• The Abrahamic Covenant:\n  - Call of Abraham (Genesis 12): Commanded to leave his homeland (Ur/Haran) for an unknown promised land. God promises: a great nation, divine blessing, a great name, and through him all families of earth will be blessed.\n  - Circumcision (Genesis 17): The physical sign of the perpetual covenant between God and Abraham's descendants.\n  - Testing of Faith (Genesis 22): God commands Abraham to sacrifice Isaac on Mount Moriah; Abraham demonstrates absolute trust; God provides a ram in the thicket.\n• Moses and the Sinai Covenant:\n  - The Call of Moses (Exodus 3): At the burning bush on Mount Horeb; divine revelation of the sacred name YHWH (\"I AM WHO I AM\").\n  - The Passover (Exodus 12): Blood of the unblemished lamb smeared on doorposts protects Hebrew firstborns from the angel of death; leads to the Exodus deliverance.\n  - The Sinai Covenant (Exodus 20): The Ten Commandments (Decalogue) delivered on stone tablets—establishing moral obligations toward God (1–4) and community (5–10).",
