    "description": "Leadership models: Joshua's courage and crossing of the Jordan, Deborah's judicial and military courage, and Gideon's fleece and deliverance.",
    "isFreeTrial": true,
    "isVip": false,
    "keyNotes": "• Joshua's Commission (Joshua 1):\n  - Appointed successor to Moses; commanded to \"Be strong and courageous; do not be afraid... for the Lord your God is with you wherever you go.\"\n  - Successfully led Israel across the parted Jordan River and captured the fortified city of Jericho through obedience to divine military strategy.\n• Deborah the Prophetess and Judge (Judges 4–5):\n  - Only female judge in ancient Israel; administered justice under the Palm of Deborah.\n  - Inspired and accompanied military commander Barak to victory against Sisera, general of the Canaanite king Jabin.\n  - Sisera fled and was assassinated by Jael, wife of Heber the Kenite, fulfilling Deborah's prophecy that the honor of the day would belong to a woman.\n• Gideon's Faith and Deliverance (Judges 6–7):\n  - Called while threshing wheat in a winepress to hide from Midianite marauders; demanded confirmation signs through the fleece of wool.\n  - With God-instructed reduction of his army from 32,000 to just 300 men (the water-lapping test), routed Midian with clay jars, torches, and trumpets.",
