    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Demand for Kingship (1 Samuel 8):\n  - Israel demanded a king to be like surrounding nations; Samuel warned of royal oppression (taxes, conscription, forced labor); God considered the demand a rejection of His direct theocratic rule.\n• King Saul:\n  - First king; anointed by Samuel. Disobeyed God through unauthorized priestly sacrifice at Gilgal and failing to carry out total destruction of the Amalekites (sparing King Agag and livestock). Samuel declared: \"To obey is better than sacrifice.\"\n• King David:\n  - Anointed as a shepherd boy; demonstrated faith by slaying Goliath; showed respect for God's anointed by refusing to kill Saul in the cave.\n  - Established Jerusalem as capital. Committed grave sins of adultery with Bathsheba and orchestrated murder of Uriah the Hittite; deeply repented when confronted by prophet Nathan (Psalm 51).\n• King Solomon:\n  - Prayed for wisdom to govern rather than riches; built the magnificent First Temple in Jerusalem.\n  - Tragic Downfall: Marrying numerous foreign idolatrous wives who turned his heart toward pagan gods (Ashtoreth, Chemosh, Molech), causing the kingdom's post-death split.",
