    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Purpose of Miracles: Not entertainment or magical showmanship; they are signs demonstrating the arrival of the Kingdom of God, divine compassion for human suffering, and Christ's authority over nature, sickness, demons, and death.\n• Four Categories of Miracles:\n  - Nature Miracles: Calming the storm on Lake Galilee, turning water into wine at Cana, walking on the sea, feeding the 5,000.\n  - Healing Miracles: Healing the centurion's servant, the woman with the issue of blood, the ten lepers.\n  - Exorcisms: Casting out Legion in the Gerasene demoniac.\n  - Resurrections: Raising Lazarus, Jairus' daughter, and the widow of Nain's son.\n• The Parables of Jesus: Earthly stories with heavenly meanings.\n  - Parables of the Kingdom: Sower and the Soils, Mustard Seed, Hidden Treasure.\n  - Parables of Mercy & Grace: Prodigal Son, Lost Sheep, Lost Coin (Luke 15).\n  - Parables of Social Responsibility: The Good Samaritan (defining true neighborliness) and the Rich Man and Lazarus.",
