    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Nature of the Epistle of James:\n  - Practical manual of Christian wisdom literature, attributed to James, brother of Jesus and leader of the Jerusalem church.\n• Faith and Works (James 2:14–26):\n  - Faith without accompanying righteous actions is dead and useless: \"Even the demons believe—and shudder!\"\n  - Genuine living faith produces compassionate works: feeding the hungry, clothing the destitute, and protecting orphans and widows.\n  - Paul and James agree: Paul stresses the ROOT of salvation (faith alone); James stresses the FRUIT of salvation (good deeds prove faith).\n• Sins of the Tongue (James 3):\n  - The tongue is a small rudder steering a huge ship; a tiny spark setting a vast forest ablaze; an untamable world of unrighteousness. Believers must not bless God and curse people with the same mouth!\n• Impartiality & Prayer:\n  - Forbids favoritism: Giving VIP seats to the wealthy in gold rings while despising the poor in dirty clothes violates the royal law of love.\n  - Prayer of Faith: Call church elders to anoint the sick with oil in the name of the Lord.",
