    "keyNotes": "• The Outpouring of the Holy Spirit (Acts 2):\n  - Fulfillment of Joel's prophecy: \"I will pour out my Spirit on all flesh.\"\n  - Dramatic Signs on Pentecost: A sound like the rush of a violent wind, divided tongues as of fire resting on each disciple, and speaking in other tongues as the Spirit gave them utterance.\n  - Peter's Bold Defense: Refuted claims that the apostles were drunk with wine (\"it is only the third hour of the day - 9:00 AM\"); preached Christ's resurrection, leading to 3,000 converts baptized.\n• Spiritual Gifts (Charismata) in 1 Corinthians 12:\n  - Unity in Diversity: \"There are varieties of gifts, but the same Spirit; varieties of service, but the same Lord.\"\n  - Gifts include: The word of wisdom, word of knowledge, faith, gifts of healing, working of miracles, prophecy, distinguishing between spirits, tongues, and interpretation of tongues.\n  - The Body Metaphor: Just as the human body consists of many members (eyes, ears, hands, feet) that all need one another, no believer can say to another, \"I have no need of you.\"\n• The Supremacy of Love (1 Corinthians 13):\n  - Paul declares that even if one speaks in the tongues of mortals and angels, has prophetic powers to move mountains, or gives all possessions to the poor, without Love (*Agape*), it profits nothing.\n  - \"Love is patient, love is kind; it does not envy, it does not boast... So now faith, hope, and love abide, these three; but the greatest of these is love.\"",
