    "keyNotes": "• Christian Duty to Secular Civil Authorities (Romans 13:1–7):\n  - Divine Ordinance: \"Let every person be subject to the governing authorities; for there is no authority except from God, and those that exist have been instituted by God.\"\n  - Purpose of Government: The civil ruler is \"God's servant for your good\" to punish evil-doers and reward righteous conduct.\n  - Civic Duties: Christians must obey laws not only because of fear of punishment, but for the sake of conscience. Christians must pay taxes and tolls, and give respect and honor to state officials.\n  - Limits of Obedience: When a civil government orders believers to violate God's moral commandments, \"we must obey God rather than human beings\" (Acts 5:29).\n• Wealth, Money & True Stewardship (1 Timothy 6:6–19):\n  - Godliness with Contentment: \"Godliness with contentment is great gain. For we brought nothing into the world, and we can take nothing out of it.\"\n  - The Danger of Greed: \"For the love of money is a root of all kinds of evils. It is through this craving that some have wandered away from the faith.\" (Note: Money itself is not evil; it is the *love* and obsession with money that causes ruin).\n  - Charge to the Rich: Do not be arrogant or set hopes on the uncertainty of riches; be rich in good works, generous, and ready to share.\n• Combating Corruption & Promoting Social Justice in Ghana:\n  - Christians are called to be the \"salt of the earth\" and \"light of the world\" (Matthew 5:13–16), refusing bribes in public office and speaking against injustice.",
