    "keyNotes": "• Clifford Constitution of 1916: Expanded Legislative Council to 21 members; introduced first token representation of paramount chiefs (e.g. Nana Ofori Atta I).\n• Guggisberg Constitution of 1925:\n  - Milestone: Introduced the elective principle for the first time in the Gold Coast (3 municipal seats: Accra, Cape Coast, Sekondi).\n  - Created Provincial Councils of Chiefs to elect 6 chiefs to the Legislative Council.\n• Burns Constitution of 1946:\n  - Historic landmark: Created the first African non-official majority in any British African legislative council.\n  - United the Colony and Asante for legislative purposes for the very first time. Northern Territories remained excluded.\n• Coussey Constitution of 1951:\n  - Formulated by an all-African committee following the 1948 riots. Created an Executive Council with African ministers and Leader of Government Business.\n• Nkrumah's 1954 Constitution:\n  - Established an all-African Cabinet directly responsible to an all-elected Legislative Assembly; ended gubernatorial presence in cabinet; universal adult suffrage introduced.",
