    "keyNotes": "• Principles of Ghana's Foreign Policy:\n  - Total Liberation of Africa from Colonialism & Apartheid: Historically declared by Nkrumah: \"The independence of Ghana is meaningless unless it is linked up with the total liberation of the African continent.\"\n  - Pan-Africanism: Promoting continental integration, African unity, and economic cooperation.\n  - Non-Alignment: Refusing to align automatically with rival Cold War superpowers; maintaining neutrality and global peace.\n  - Respect for Sovereignty & Territorial Integrity of all nations.\n  - Peaceful Settlement of International Disputes.\n• Ghana's Roles in International Organizations:\n  - United Nations (UN): Leading contributor to international peacekeeping missions (Congo, Lebanon, Liberia, South Sudan). Kofi Annan served as UN Secretary-General (1997–2006).\n  - African Union (AU): Founding member of OAU (1963); champion of African peace architecture.\n  - ECOWAS: Founding member (1975); hosted key peace accords and contributed troops to ECOMOG during the Liberian and Sierra Leonean civil wars.",
