    "description": "Structure of the courts (Superior vs. Lower courts), original, appellate, and supervisory jurisdiction of the Supreme Court, and judicial review.",
    "isFreeTrial": false,
    "isVip": true,
    "keyNotes": "• Structure of the Judicial System in Ghana (Article 125, 1992 Constitution):\n  - Superior Courts of Judicature:\n    1. The Supreme Court: Highest court of the land; presided over by the Chief Justice. Possesses original jurisdiction in interpreting the Constitution, appellate jurisdiction from Court of Appeal, and supervisory jurisdiction over all lower courts. Its decisions bind all other courts.\n    2. Court of Appeal: Hears appeals from High Court and Regional Tribunals.\n    3. High Court: Original jurisdiction in all criminal and civil matters; enforces Fundamental Human Rights; issues prerogative writs (Habeas Corpus, Mandamus, Certiorari, Prohibition).\n  - Lower Courts: Circuit Courts, District Courts, Juvenile Courts.\n• Safeguards of Judicial Independence:\n  - Salaries and retirement benefits charged directly to the Consolidated Fund (cannot be reduced by the President or Parliament).\n  - Security of tenure: Superior court judges retire at age 70 and cannot be removed except for stated misbehavior or physical/mental infirmity investigated by a judicial tribunal.",
