    "keyNotes": "• Formation & Objectives of ECOWAS:\n  - Founded on May 28, 1975, through the Treaty of Lagos, initiated by General Yakubu Gowon of Nigeria and President Gnassingbé Eyadéma of Togo.\n  - Secretariat/Commission headquartered in Abuja, Nigeria.\n  - Primary Goal: Promote economic cooperation, market integration, and collective self-reliance among 15 West African nations.\n• Key Achievements:\n  - Free Movement Protocol: Abolition of visas for citizens traveling within the sub-region for stays up to 90 days.\n  - Peacekeeping & Conflict Resolution: ECOMOG interventions restored stability during the civil wars in Liberia and Sierra Leone.\n  - ECOWAS Trade Liberalization Scheme (ETLS): Duty-free and quota-free trade for local originating industrial goods.\n• Contemporary Challenges:\n  - Political instability and recurring military coups in the Sahel (Mali, Burkina Faso, Niger announcing intent to withdraw).\n  - Terrorist insurgencies (Boko Haram, ISWAP, JNIM) threatening coastal West African states.\n  - Anglophone versus Francophone cultural/linguistic divisions and non-tariff trade barriers.",
