    "keyNotes": "• Evolution from OAU to AU:\n  - Organization of African Unity (OAU): Founded on May 25, 1963, in Addis Ababa, Ethiopia. Primary historical mission was the total eradication of colonialism and apartheid in Africa.\n  - African Union (AU): Formally launched in Durban, South Africa in July 2002 (Sirte Declaration 1999) to shift focus toward socio-economic integration, democracy, and good governance.\n• Key Organs & Mechanisms:\n  - The Assembly of Heads of State: Supreme policy-making organ.\n  - Peace and Security Council (PSC): 15-member body tasked with conflict prevention, management, and resolution; can deploy the African Standby Force (ASF).\n  - African Peer Review Mechanism (APRM): Voluntary self-monitoring governance tool to assess democracy and human rights (Ghana was the first African country to undergo peer review in 2006).\n  - African Court on Human and Peoples' Rights (Arusha, Tanzania).\n• Agenda 2063: The 50-year master strategic blueprint for transforming Africa into the global powerhouse of the future (\"The Africa We Want\").",
